CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),legal_name text NOT NULL,country char(2) NOT NULL,kyb_status text NOT NULL CHECK(kyb_status IN('pending','verified','rejected')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE payment_intents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),idempotency_key text NOT NULL,source_currency char(3) NOT NULL,target_currency char(3) NOT NULL,amount_minor numeric(38,0) NOT NULL CHECK(amount_minor>0),status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(organization_id,idempotency_key));
CREATE TABLE ledger_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),journal_id uuid NOT NULL,account text NOT NULL,currency char(3) NOT NULL,debit_minor numeric(38,0) NOT NULL DEFAULT 0 CHECK(debit_minor>=0),credit_minor numeric(38,0) NOT NULL DEFAULT 0 CHECK(credit_minor>=0),created_at timestamptz NOT NULL DEFAULT now(),CHECK((debit_minor=0)<>(credit_minor=0)));
CREATE TABLE audit_events(id bigserial PRIMARY KEY,organization_id uuid,actor_id text NOT NULL,action text NOT NULL,object_type text NOT NULL,object_id text NOT NULL,request_id text NOT NULL,payload_hash text NOT NULL,occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_object_idx ON audit_events(object_type,object_id,occurred_at);